def chunks(words: list[str], size: int, overlap: int) -> list[dict]:
    step = size - overlap
    return [
        {"text": " ".join(words[i:i+size]), "start": i, "doc": "procedure-securite-v3"}
        for i in range(0, len(words), step) if words[i:i+size]
    ]

result = chunks("couper le courant avant toute intervention sur le boîtier".split(), 4, 1)
for c in result:
    print(c["start"], c["doc"], c["text"])
